UPDATE TB_STUDENT_ACCESS_SESSION
SET TEACHER_STUDENT_ACCESS_ID = #{teacherStudentAccessId,jdbcType=NUMERIC},
    UPDATED_AT = #{updatedAt}
WHERE STUDENT_ACCESS_SESSION_ID = #{studentAccessSessionId}
  AND STUDENT_ID = #{studentId}
  AND SESSION_STATUS = 'ACTIVE'
  AND REVOKED_AT IS NULL
